// fin.dated_charges's members: one function per member, each declared by the //kavun:member directive in its doc
// comment. The table, datedChargesMethods, and the member entries of docs/reference/types/fin_dated_charges.md
// (alphabetical, so the order here is free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a
// directive or a doc comment.

// Report truthiness: the zero table is falsy.
//
//kavun:member is_true pure () -> bool
func datedChargesIsTrue(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	t, err := core.ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return core.Undefined, err
	}
	return core.BoolValue(t), nil
}

